import {board,getPin} from './boards.js';
import {definitions} from './components.js';
import {lessons} from './content.js';
import {analyze,checkLesson} from './circuit.js';

const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={play:'<path d="m7 4 12 8-12 8z"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="1"/>',plus:'<path d="M12 5v14M5 12h14"/>',undo:'<path d="m9 4-5 5 5 5M4 9h9a7 7 0 0 1 0 14"/>',wire:'<path d="M5 5v9a5 5 0 0 0 10 0V5"/><circle cx="5" cy="4" r="2"/><circle cx="15" cy="4" r="2"/>',check:'<path d="m5 12 4 4L19 6"/>',trash:'<path d="M4 7h16M9 7V4h6v3M7 7l1 13h8l1-13M10 10v7M14 10v7"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[name]||''}</svg>`;
const lesson=lessons.find(l=>l.id===location.hash.slice(1))||lessons[0],KEY='pi-lab-workspace-v2-'+lesson.id,history=[];
let state={components:structuredClone(lesson.components),wires:[],code:lesson.starterCode},selected=null,from=null,running=false,worker=null,outputs={},pressed={},observed=new Set(),zoom=1,activeTab='answer',audioCtx=null,oscillator=null,volume=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.components)&&saved.components.length<=24&&Array.isArray(saved.wires)&&saved.wires.length<=80&&typeof saved.code==='string'&&saved.code.length<50000&&saved.components.every(c=>definitions[c.type]&&typeof c.id==='string'&&/^[A-Za-z0-9_-]+$/.test(c.id)&&Number.isFinite(c.x)&&Number.isFinite(c.y))){state=saved;const ids=new Set([...board.pins.map(p=>p.id),...state.components.flatMap(c=>definitions[c.type].pins.map(p=>`${c.id}:${p.name}`))]);state.wires=state.wires.filter(w=>ids.has(w.a)&&ids.has(w.b));}}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saved').textContent='この端末に保存済み';}catch{$('#saved').textContent='保存できません';}}
function snapshot(){history.push(structuredClone(state));if(history.length>40)history.shift();}
function mutate(fn){stop(false);snapshot();fn();selected=null;from=null;observed.clear();save();renderStage();renderReference();}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,2600);}
function pinName(id){if(id.startsWith('pi:')){const p=getPin(id);return p?`${p.label} · 物理${p.physical}`:id;}const [cid,pid]=id.split(':');const c=state.components.find(c=>c.id===cid);return c?`${definitions[c.type].name} ${cid} · ${definitions[c.type].pins.find(p=>p.name===pid)?.label||pid}`:id;}

$('#app').innerHTML=`
 <div class="lesson-heading"><div><span class="eyebrow">PLAYGROUND <span class="sample-badge">${esc(lesson.label)}</span></span><h1>${esc(lesson.title)}</h1><p>${esc(lesson.description)}</p>${lessons.length>1?`<label class="lesson-picker">教材 <select id="lesson-select">${lessons.map(l=>`<option value="${esc(l.id)}" ${l.id===lesson.id?'selected':''}>${esc(l.title)}</option>`).join('')}</select></label>`:''}</div><div class="lesson-actions"><span id="saved">この端末に保存</span><button id="reset" class="quiet">最初から</button></div></div>
 <div class="workspace">
  <section class="workbench panel" aria-label="回路の作業台"><div class="panel-header"><div class="panel-title">${icon('wire')}<h2>作業台</h2><span id="run-state" class="state-label">停止中</span></div><div class="toolbar"><button class="quiet icon-btn" id="undo" title="元に戻す" aria-label="元に戻す">${icon('undo')}</button><button id="add-toggle" class="secondary">${icon('plus')}部品を追加</button></div></div>
   <div class="parts-tray" id="parts-tray" hidden>${Object.entries(definitions).map(([type,d])=>`<button data-add="${type}"><img src="./assets/${d.asset}" alt=""><span>${d.name}</span></button>`).join('')}</div>
   <div class="canvas-viewport" id="viewport"><div class="canvas-size" id="canvas-size"><div class="canvas" id="canvas"><div class="board-label">RASPBERRY PI 4 <span>40-PIN GPIO</span></div><img class="board-image" src="${board.image}" alt="真上から見たRaspberry Pi 4基板の生成画像" draggable="false"><div class="header-mask"></div><div id="board-pins"></div><svg id="wires" class="wires" viewBox="0 0 850 560" aria-label="接続線"></svg><div id="parts"></div><div class="canvas-note" id="canvas-note">端子 → 端子 の順にタップして接続</div></div></div></div>
   <div class="canvas-footer"><span id="selection-note">部品名をドラッグして移動</span><div class="zoom-tools"><button id="zoom-out" aria-label="縮小">−</button><button id="fit" title="全体を表示">全体</button><button id="zoom-in" aria-label="拡大">＋</button></div></div>
   <div id="selected-tools" class="selected-tools" hidden></div>
   <details class="connection-tools"><summary>端子名を選んで配線 <span>スマホでも接続しやすい</span></summary><div class="connection-form"><label>接続元<select id="from-pin"></select></label><span class="connection-arrow">→</span><label>接続先<select id="to-pin"></select></label><button id="connect" class="secondary">接続</button></div></details>
   <div id="component-inputs" class="component-inputs" hidden></div>
   <div class="wiring-status" id="wiring-status" role="status"></div>
   <details class="connection-list"><summary>接続一覧 <span id="wire-count"></span></summary><div id="wire-list"></div></details>
  </section>
  <div class="side-panels"><section class="editor panel"><div class="panel-header"><div class="panel-title"><span class="file-dot"></span><h2>main.py</h2><span class="language">Python</span></div><button id="run" class="run">${icon('play')}実行</button></div><div class="code-area"><div id="line-numbers" aria-hidden="true"></div><textarea id="code" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" aria-label="Pythonコード"></textarea></div><div class="console-header"><span>出力</span><button id="clear-console" class="quiet">クリア</button></div><pre class="console" id="console" role="log" aria-live="polite">実行すると、ここに結果が表示されます。</pre></section>
   <section class="reference panel"><div class="reference-tabs" role="tablist" aria-label="学習ガイド"><button role="tab" id="tab-answer" data-tab="answer" aria-selected="true" aria-controls="reference-content">答え</button><button role="tab" id="tab-steps" data-tab="steps" aria-selected="false" aria-controls="reference-content">手順</button><button role="tab" id="tab-check" data-tab="check" aria-selected="false" aria-controls="reference-content">確認</button></div><div id="reference-content" role="tabpanel" aria-labelledby="tab-answer"></div></section>
  </div>
 </div><footer class="app-footer"><span>教材はこれから追加。まずは、この作業台で。</span><span>GPIOの動作を再現する学習用シミュレータ</span></footer>`;

function pinPosition(id){if(id.startsWith('pi:')){const p=getPin(id);if(!p)return null;return {x:116+Math.floor((p.physical-1)/2)*12.35,y:p.physical%2===0?183:197};}const [cid,pid]=id.split(':'),c=state.components.find(c=>c.id===cid);if(!c)return null;const d=definitions[c.type],p=d.pins.find(p=>p.name===pid);return p?{x:c.x+d.width*p.x/100,y:c.y+d.height*p.y/100}:null;}
function wireColor(w){const a=getPin(w.a),b=getPin(w.b);return [a,b].some(p=>p?.type==='ground')?'#344654':[a,b].some(p=>p?.type==='power')?'#d96153':'#cc9141';}
function renderWires(){
 $('#wires').innerHTML=state.wires.map((w,i)=>{const a=pinPosition(w.a),b=pinPosition(w.b);if(!a||!b)return '';const top=Math.min(a.y,b.y)-38-(i%4)*14;const path=`M${a.x},${a.y} C${a.x},${top} ${b.x},${top} ${b.x},${b.y}`;return `<g data-wire="${i}" class="wire ${selected?.wire===i?'selected':''}" tabindex="0" role="button" aria-label="${esc(pinName(w.a)+' から '+pinName(w.b))}"><path d="${path}" class="wire-hit"/><path d="${path}" class="wire-line" stroke="${wireColor(w)}"/></g>`;}).join('');
 $('#wire-count').textContent=`${state.wires.length}本`;
 $('#wire-list').innerHTML=state.wires.length?state.wires.map((w,i)=>`<div class="wire-row"><span>${esc(pinName(w.a))}<br><span class="muted">→ ${esc(pinName(w.b))}</span></span><button class="quiet icon-btn" data-remove-wire="${i}" aria-label="接続${i+1}を削除">${icon('trash')}</button></div>`).join(''):'<p class="muted">まだ配線されていません。</p>';
}
function renderStage(){
 $('#board-pins').innerHTML=board.pins.map(p=>{const pos=pinPosition(p.id);return `<button class="pin board-pin ${p.type}${from===p.id?' pending':''}" style="left:${pos.x}px;top:${pos.y}px" data-pin="${p.id}" aria-label="${esc(pinName(p.id))}" title="${esc(pinName(p.id))}"></button>`;}).join('');
 $('#parts').innerHTML=state.components.map(c=>{const d=definitions[c.type];return `<div class="component ${selected?.part===c.id?'selected':''}" style="left:${c.x}px;top:${c.y}px;width:${d.width}px" data-component="${c.id}"><button class="component-handle" data-drag="${c.id}" aria-label="${esc(d.name+' '+c.id)}を選択・移動">${d.name}<span>${c.type==='resistor'?esc(c.value)+'Ω':esc(c.id)}</span></button><div class="part-art" style="height:${d.height}px"><img id="image-${c.id}" src="./assets/${c.type==='resistor'?`resistor-${[330,1000,10000].includes(c.value)?c.value:330}.svg`:d.asset}" alt="${d.name}" draggable="false">${c.type==='button'?`<button class="press-button" data-press="${c.id}" aria-label="${esc(c.id)}を押す"></button>`:''}${c.type==='buzzer'?`<span class="buzzer-state" id="buzzer-${c.id}">OFF</span>`:''}${d.pins.map(p=>`<button class="pin part-pin${from===`${c.id}:${p.name}`?' pending':''}" style="left:${p.x}%;top:${p.y}%" data-pin="${c.id}:${p.name}" title="${esc(pinName(`${c.id}:${p.name}`))}" aria-label="${esc(pinName(`${c.id}:${p.name}`))}"><span>${p.label}</span></button>`).join('')}</div></div>`;}).join('');
 renderWires();renderTools();renderPinSelectors();$('#component-inputs').hidden=!state.components.some(c=>c.type==='button');$('#component-inputs').innerHTML=state.components.filter(c=>c.type==='button').map(c=>`<button class="secondary" data-press="${c.id}" aria-label="${esc(c.id)}を押す">ボタン ${esc(c.id)} を押す</button>`).join('');updateCircuit();$('#undo').disabled=history.length===0;
 $('#selection-note').textContent=from?`${pinName(from)} → 接続先を選んでください`:'部品名をドラッグして移動';
}
function renderPinSelectors(){const options='<option value="">端子を選択</option>'+`<optgroup label="Raspberry Pi">${board.pins.map(p=>`<option value="${p.id}">${esc(pinName(p.id))}</option>`).join('')}</optgroup>`+state.components.map(c=>`<optgroup label="${esc(definitions[c.type].name+' '+c.id)}">${definitions[c.type].pins.map(p=>`<option value="${c.id}:${p.name}">${esc(pinName(`${c.id}:${p.name}`))}</option>`).join('')}</optgroup>`).join('');const a=$('#from-pin').value,b=$('#to-pin').value;$('#from-pin').innerHTML=options;$('#to-pin').innerHTML=options;$('#from-pin').value=from||a;$('#to-pin').value=b;}
function renderTools(){const area=$('#selected-tools');area.hidden=!selected;if(!selected)return;if(selected.wire!==undefined){area.innerHTML=`<span>接続線 ${selected.wire+1}</span><button class="quiet danger" id="delete-selected">${icon('trash')}削除</button>`;}else{const c=state.components.find(c=>c.id===selected.part);if(!c){area.hidden=true;return;}area.innerHTML=`<span>${definitions[c.type].name} ${esc(c.id)}</span>${c.type==='resistor'?`<label>抵抗値 <select id="resistance">${[330,1000,10000].map(v=>`<option value="${v}" ${c.value===v?'selected':''}>${v} Ω</option>`).join('')}</select></label>`:''}<button class="quiet danger" id="delete-selected">${icon('trash')}削除</button>`;}}
function renderReference(){const target=$('#reference-content');target.setAttribute('aria-labelledby',`tab-${activeTab}`);document.querySelectorAll('[data-tab]').forEach(el=>{el.setAttribute('aria-selected',el.dataset.tab===activeTab);el.tabIndex=el.dataset.tab===activeTab?0:-1;});
 if(activeTab==='answer'){target.innerHTML=`<div class="reference-title"><h3>配線の答え</h3><button class="quiet accent" id="apply-wiring">作業台に置く</button></div><div class="answer-wires">${lesson.answer.connections.map(([a,b],i)=>`<div><span class="step-count">${i+1}</span><p>${esc(a)}<br><span class="muted">→ ${esc(b)}</span></p></div>`).join('')}</div><div class="reference-title"><h3>コードの答え</h3><button class="quiet accent" id="apply-code">エディタに入れる</button></div><pre class="answer-code">${esc(lesson.answer.code)}</pre>`;}
 if(activeTab==='steps')target.innerHTML=lesson.steps.map((s,i)=>`<div class="step"><span class="step-count">${i+1}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div></div>`).join('')+'<p class="reference-note">この1題は操作確認用です。学習コンテンツは後から追加します。</p>';
 if(activeTab==='check'){const checks=checkLesson(lesson,state.components,state.wires,observed);target.innerHTML=`<h3>今の回路を確認</h3><div class="check-list">${checks.map(c=>`<div class="check-row ${c.passed?'passed':''}"><span>${c.passed?icon('check'):'○'}</span>${esc(c.label)}</div>`).join('')}</div><p class="reference-note">${checks.every(c=>c.passed)?'配線と点灯を確認できました。点滅の速さを変えてみましょう。':'配線し、「実行」で動作を確認しましょう。'}</p>`;}}
function connect(a,b){if(!a||!b)return toast('接続元と接続先を選んでください。');if(a===b)return toast('違う端子を選んでください。');if(state.wires.some(w=>w.a===a&&w.b===b||w.a===b&&w.b===a))return toast('すでにつながっています。');if(state.wires.length>=80)return toast('配線は80本までです。');mutate(()=>state.wires.push({a,b}));}
function selectPin(id){if(running)stop(false);if(from===id){from=null;renderStage();return;}if(from){connect(from,id);return;}from=id;selected=null;renderStage();}
function appendLog(text){const output=$('#console');if(output.dataset.empty!=='false'){output.textContent='';output.dataset.empty='false';}output.textContent=(output.textContent+text).slice(-10000);output.scrollTop=output.scrollHeight;}
function updateCircuit(){const result=analyze(state.components,state.wires,outputs,pressed);for(const c of state.components){const value=result.states[c.id]?.value||0;if(value>0)observed.add(c.id);if(c.type==='led'){const img=$(`#image-${c.id}`);if(img){img.src=`./assets/led-red-${value>0?'on':'off'}.svg`;img.style.opacity=value>0?Math.max(.4,value):1;img.classList.toggle('lit',value>0);}}if(c.type==='button'){const img=$(`#image-${c.id}`);if(img)img.src=`./assets/pushbutton-${pressed[c.id]?'pressed':'released'}.svg`;}if(c.type==='buzzer'){const el=$(`#buzzer-${c.id}`);if(el){el.textContent=value?'ON':'OFF';el.classList.toggle('on',value>0);}}}
 const status=$('#wiring-status');status.classList.toggle('error',result.issues.length>0);status.innerHTML=result.issues.length?`${icon('wire')}<span>${esc(result.issues[0].message)}</span>`:state.wires.length?`${icon('check')}<span>${running?'実行中。回路の変化を確認できます。':'配線済み。「実行」で動きを確認できます。'}</span>`:`${icon('wire')}<span>右の答えを見ながら配線してみましょう。</span>`;
 if(worker)worker.postMessage({type:'inputs',values:result.inputs});
 if(volume)volume.gain.value=running&&state.components.some(c=>c.type==='buzzer'&&result.states[c.id]?.value>0)?0.035:0;
 if(result.issues.length&&running){appendLog('\n配線エラー: '+result.issues[0].message+'\n');stop(false);}
 if(activeTab==='check')renderReference();return result;}
function stop(log=true){if(worker){worker.terminate();worker=null;}const wasRunning=running;running=false;outputs={};pressed={};activePresses.clear();if(volume)volume.gain.value=0;$('#run').innerHTML=icon('play')+'実行';$('#run').classList.remove('is-running');$('#run-state').textContent='停止中';$('#run-state').classList.remove('live');if(log&&wasRunning)appendLog('\n停止しました。\n');updateCircuit();}
function run(){if(running){stop();return;}outputs={};const preflight=analyze(state.components,state.wires,outputs,pressed);outputs={};if(preflight.issues.length){appendLog(preflight.issues[0].message+'\n');toast('配線を確認してください。');updateCircuit();return;}
 $('#console').textContent='';$('#console').dataset.empty='false';observed.clear();running=true;$('#run').innerHTML=icon('stop')+'停止';$('#run').classList.add('is-running');$('#run-state').textContent='実行中';$('#run-state').classList.add('live');
 try{worker=new Worker('./src/python-worker.js');const activeWorker=worker;worker.onmessage=({data})=>{if(worker!==activeWorker)return;if(data.type==='gpio'){outputs[data.pin]=data.value;updateCircuit();}if(data.type==='stdout')appendLog(data.text);if(data.type==='error'){appendLog(data.message+'\n');stop(false);}if(data.type==='done'){appendLog('\n実行が完了しました。出力は停止まで保持されます。\n');worker.terminate();worker=null;$('#run-state').textContent='コード終了';}};worker.onerror=()=>{appendLog('実行環境を読み込めませんでした。ページを再読み込みしてください。\n');stop(false);};const result=updateCircuit();if(worker){worker.postMessage({type:'inputs',values:result.inputs});worker.postMessage({type:'run',code:state.code});}
 if(state.components.some(c=>c.type==='buzzer')){audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();if(!oscillator){oscillator=audioCtx.createOscillator();volume=audioCtx.createGain();volume.gain.value=0;oscillator.frequency.value=880;oscillator.connect(volume).connect(audioCtx.destination);oscillator.start();}}
 }catch(error){appendLog(String(error)+'\n');stop(false);}}
function updateLineNumbers(){$('#line-numbers').textContent=state.code.split('\n').map((_,i)=>i+1).join('\n');}
function setZoom(next){zoom=Math.max(.38,Math.min(1.8,next));$('#canvas').style.transform=`scale(${zoom})`;$('#canvas-size').style.width=`${850*zoom}px`;$('#canvas-size').style.height=`${560*zoom}px`;}
function fit(){setZoom(($('#viewport').clientWidth-2)/850);}

$('#code').value=state.code;updateLineNumbers();
$('#code').addEventListener('input',e=>{state.code=e.target.value;updateLineNumbers();save();});$('#code').addEventListener('scroll',e=>$('#line-numbers').scrollTop=e.target.scrollTop);
$('#code').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target,start=t.selectionStart,end=t.selectionEnd;t.setRangeText('    ',start,end,'end');state.code=t.value;updateLineNumbers();save();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run();}});
$('#run').onclick=run;$('#connect').onclick=()=>connect($('#from-pin').value,$('#to-pin').value);$('#add-toggle').onclick=()=>$('#parts-tray').hidden=!$('#parts-tray').hidden;
$('#undo').onclick=()=>{if(!history.length)return;stop(false);state=history.pop();$('#code').value=state.code;updateLineNumbers();from=null;selected=null;observed.clear();save();renderStage();renderReference();};
$('#reset').onclick=()=>{mutate(()=>state={components:structuredClone(lesson.components),wires:[],code:lesson.starterCode});$('#code').value=state.code;updateLineNumbers();toast('最初の状態に戻しました。元に戻すこともできます。');};
$('#zoom-in').onclick=()=>setZoom(zoom+.2);$('#zoom-out').onclick=()=>setZoom(zoom-.2);$('#fit').onclick=fit;
$('#clear-console').onclick=()=>$('#console').textContent='';$('#help-button').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();
document.addEventListener('click',e=>{const pin=e.target.closest('[data-pin]');if(pin){selectPin(pin.dataset.pin);return;}const wire=e.target.closest('[data-wire]');if(wire){selected={wire:Number(wire.dataset.wire)};from=null;renderWires();renderTools();return;}const add=e.target.closest('[data-add]');if(add){if(state.components.length>=24)return toast('部品は24個までです。');const type=add.dataset.add;mutate(()=>state.components.push({id:type+Date.now().toString(36),type,x:540+(state.components.length%3)*45,y:150+(state.components.length%4)*85,value:330}));toast(definitions[type].name+'を追加しました。');return;}const tab=e.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;renderReference();return;}const remove=e.target.closest('[data-remove-wire]');if(remove){mutate(()=>state.wires.splice(Number(remove.dataset.removeWire),1));return;}
 if(e.target.closest('#apply-wiring')){mutate(()=>{state.components=structuredClone(lesson.components);state.wires=structuredClone(lesson.answer.wires);});toast('答えの配線を置きました。');}
 if(e.target.closest('#apply-code')){snapshot();state.code=lesson.answer.code;$('#code').value=state.code;updateLineNumbers();save();toast('答えのコードを入れました。');}
 if(e.target.closest('#delete-selected')){const old=selected;mutate(()=>{if(old.wire!==undefined)state.wires.splice(old.wire,1);else{state.components=state.components.filter(c=>c.id!==old.part);state.wires=state.wires.filter(w=>!w.a.startsWith(old.part+':')&&!w.b.startsWith(old.part+':'));}});}
});
document.addEventListener('change',e=>{if(e.target.id==='resistance'){const id=selected?.part,value=Number(e.target.value);mutate(()=>{state.components.find(c=>c.id===id).value=value;});}});
document.addEventListener('keydown',e=>{const wire=e.target.closest('[data-wire]');if(wire&&(e.key==='Enter'||e.key===' ')){e.preventDefault();wire.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='Escape'){from=null;selected=null;renderStage();}if(e.target.matches('[data-tab]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=['answer','steps','check'];activeTab=tabs[(tabs.indexOf(activeTab)+(e.key==='ArrowRight'?1:2))%3];renderReference();$(`#tab-${activeTab}`).focus();}});
let drag=null;const activePresses=new Map();function refreshPressed(){pressed=Object.fromEntries([...activePresses.values()].map(id=>[id,true]));updateCircuit();}
document.addEventListener('pointerdown',e=>{const press=e.target.closest('[data-press]');if(press){e.preventDefault();press.setPointerCapture(e.pointerId);activePresses.set(e.pointerId,press.dataset.press);refreshPressed();return;}const handle=e.target.closest('[data-drag]');if(!handle)return;e.preventDefault();if(running)stop(false);const c=state.components.find(c=>c.id===handle.dataset.drag);snapshot();selected={part:c.id};from=null;drag={pointerId:e.pointerId,id:c.id,x:e.clientX,y:e.clientY,startX:c.x,startY:c.y};handle.setPointerCapture(e.pointerId);renderTools();});
document.addEventListener('pointermove',e=>{if(!drag||drag.pointerId!==e.pointerId)return;const c=state.components.find(c=>c.id===drag.id),d=definitions[c.type];c.x=Math.max(24,Math.min(825-d.width,drag.startX+(e.clientX-drag.x)/zoom));c.y=Math.max(80,Math.min(500-d.height,drag.startY+(e.clientY-drag.y)/zoom));const el=document.querySelector(`[data-component="${c.id}"]`);el.style.left=c.x+'px';el.style.top=c.y+'px';renderWires();});
const release=e=>{if(e?.pointerId!==undefined){activePresses.delete(e.pointerId);}else activePresses.clear();refreshPressed();if(drag&&(!e||e.pointerId===undefined||drag.pointerId===e.pointerId)){drag=null;save();renderStage();}};
document.addEventListener('pointerup',release);document.addEventListener('pointercancel',release);window.addEventListener('blur',()=>release());
document.addEventListener('keydown',e=>{const press=e.target.closest('[data-press]');if(press&&(e.key===' '||e.key==='Enter')){e.preventDefault();activePresses.set('key-'+press.dataset.press,press.dataset.press);refreshPressed();}});document.addEventListener('keyup',e=>{const press=e.target.closest('[data-press]');if(press){activePresses.delete('key-'+press.dataset.press);refreshPressed();}});
renderStage();renderReference();fit();save();let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(fit,160);});

if($('#lesson-select'))$('#lesson-select').onchange=e=>{save();location.hash=e.target.value;};window.addEventListener('hashchange',()=>location.reload());

if(matchMedia('(pointer:coarse)').matches)$('.connection-tools').open=true;
